/**
 * workforce-icon-art.ts -- vendored workforce marker/list-avatar illustration
 * assets (Live Monitoring "add WORKFORCE alongside vehicles" enhancement,
 * 2026-08-31).
 *
 * Source: designer-supplied SVG exports at
 * `/Users/apple/Desktop/Workforce icons` (read-only reference folder) --
 * copied byte-for-byte and embedded as base64 data URIs, the SAME technique
 * `domain/map/weather-station-art.ts` uses for its raster asset (kept out of
 * the render component so it only carries the wiring, not the asset bytes).
 * Unlike the weather-station raster, these source files are already SVG, so
 * the data URI stays `image/svg+xml` and scales crisply at any size.
 *
 * EMBEDDED BRAND ASSET NOTE (mirrors `VehicleIcon3D.tsx`'s docblock): this is
 * illustration artwork extracted from Figma (node ids `3439:*`, the same
 * "FAMS - Workforce Management App" file the pixel-reference nodes came
 * from), not themable UI styling -- each status variant's ring/tint colour is
 * BAKED INTO the asset (green #12B76A on-duty, orange #F79009 on-break, blue
 * #0072D6 in-transit), matching the reference screenshots exactly. This is a
 * deliberate departure from `VehicleIcon3D`'s tone-badge system (which only
 * has 4 semantic tones -- success/warning/error/muted, no "info"/blue): three
 * pre-coloured status assets sidestep extending that shared enum, per the
 * task's "do NOT build new generalized DS primitives" scope call. Kept in
 * `v5-templates` (the live-monitoring VIEW layer) rather than `ui-kit` (the
 * primitives layer) for the same reason -- this is module-specific wiring,
 * not a new design-system primitive.
 *
 * Two asset families, each keyed by `LiveWorkforceStatus` (`live-types.ts`):
 *  - `WORKFORCE_MARKER_ART`  -- the 40x71 map-pin badge (tinted fill + ring +
 *    person silhouette + pointer tail), source `Assets_on_Map Icons*.svg`.
 *  - `WORKFORCE_AVATAR_ART`  -- the 41x45 list-row/popup avatar (illustrated
 *    person + small baked-in status dot, no pointer), source
 *    `Group 1261154774/775/777.svg`.
 *
 * 2026-08-31 workforce-popup task: the vocabulary gained the spec's three
 * live states -- `in-transit` (MOVING; reuses the green art, matching the
 * reference map's green moving members and the vehicles' moving=green
 * convention), `clocked-in` (STATIC blue; the blue asset the reference uses
 * for the stationary clocked-in member), and the NEW grey `not-clocked-in`
 * (mechanical recolor of the blue asset onto the vehicles' non-reporting
 * grey: accent #0072D6→#98A2B3, tint #E6F2FC→#F2F4F7). The legacy keys stay
 * so existing callers/tests keep rendering.
 */
export type WorkforceStatusKey = 'on-duty' | 'on-break' | 'in-transit' | 'clocked-in' | 'not-clocked-in'

/** Master geometry -- `Assets_on_Map Icons*.svg`'s own viewBox (width x height). */
export const WORKFORCE_MARKER_ART_W = 40
export const WORKFORCE_MARKER_ART_H = 71

/** Master geometry -- `Group 1261154774/775/777.svg`'s own viewBox. */
export const WORKFORCE_AVATAR_ART_W = 41
export const WORKFORCE_AVATAR_ART_H = 45

export const WORKFORCE_MARKER_ART: Record<WorkforceStatusKey, string> = {
  'on-duty': 'data:image/svg+xml;base64,',
  'on-break': 'data:image/svg+xml;base64,',
  'in-transit': 'data:image/svg+xml;base64,',
  'clocked-in': 'data:image/svg+xml;base64,',
  'not-clocked-in': 'data:image/svg+xml;base64,',
}

export const WORKFORCE_AVATAR_ART: Record<WorkforceStatusKey, string> = {
  'on-duty': 'data:image/svg+xml;base64,',
  'on-break': 'data:image/svg+xml;base64,',
  'in-transit': 'data:image/svg+xml;base64,',
  'clocked-in': 'data:image/svg+xml;base64,',
  'not-clocked-in': 'data:image/svg+xml;base64,',
}
